package ir.torsepan.mobile;import org.json.*;import java.util.*;class OfflineStore{Map<String,String> values=new HashMap<>();JSONArray rows=new JSONArray();int installed;String get(String key){return values.getOrDefault(key,"");}void put(String key,String value){values.put(key,value);}boolean has(String key){return values.containsKey(key);}String device(){return "11111111-1111-4111-8111-111111111111";}JSONArray operations(){return rows;}void saveSession(String token,String refresh){put("token",token);put("refresh_token",refresh);}void installSnapshot(JSONObject data){installed++;put("snapshot",data.toString());}int pending(){int count=0;for(int i=0;i<rows.length();i++)if(!rows.getJSONObject(i).getString("state").equals("applied"))count++;return count;}void acknowledge(String id,String state,String message){for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).getString("id").equals(id)){rows.getJSONObject(i).put("state",state).put("message",message);return;}throw new IllegalStateException();}}
